package in.recallradar;
import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.math.*; import java.time.*; import java.time.format.DateTimeFormatter; import java.util.*; import java.util.stream.Collectors;
@Service @Transactional class ProductionService {private final FinishedProductRepository products;private final RecipeRepository recipes;private final RecipeIngredientRepository lines;private final ProductionBatchRepository batches;private final ProductionConsumptionRepository consumptions;private final IngredientRepository ingredients;private final LocationRepository locations;private final InventoryLotRepository lots;private final InventoryBalanceRepository balances;private final LotQuarantineRepository quarantines;private final InventoryService inventory;private final TenantService tenants;private final AuditService audit;
ProductionService(FinishedProductRepository p,RecipeRepository r,RecipeIngredientRepository li,ProductionBatchRepository b,ProductionConsumptionRepository c,IngredientRepository i,LocationRepository l,InventoryLotRepository lot,InventoryBalanceRepository bal,LotQuarantineRepository q,InventoryService in,TenantService t,AuditService a){products=p;recipes=r;lines=li;batches=b;consumptions=c;ingredients=i;locations=l;lots=lot;balances=bal;quarantines=q;inventory=in;tenants=t;audit=a;}
private void editor(Membership m){tenants.requireMasterDataEditor(m);} private String clean(String s){return s==null||s.isBlank()?null:s.trim();}
List<ProductResponse> products(Membership m){return products.findByOrganizationIdOrderByName(m.organizationId).stream().map(x->new ProductResponse(x.id.toString(),x.name,x.sku,x.unit,x.active)).toList();}
ProductResponse product(Membership m,ProductRequest r){editor(m);var x=products.save(new FinishedProduct(m.organizationId,r.name().trim(),clean(r.sku()),r.unit().trim()));audit.record(m,"PRODUCT_CREATED","FINISHED_PRODUCT",x.id,x.name);return new ProductResponse(x.id.toString(),x.name,x.sku,x.unit,x.active);}
List<RecipeResponse> recipes(Membership m){return recipes.findByOrganizationIdOrderByCreatedAtDesc(m.organizationId).stream().map(x->recipe(m,x)).toList();}
RecipeResponse createRecipe(Membership m,RecipeRequest r){editor(m);var product=products.findByIdAndOrganizationId(r.productId(),m.organizationId).orElseThrow(()->missing("Product"));var recipe=recipes.save(new Recipe(m.organizationId,product.id,r.name().trim(),r.yieldQuantity(),r.yieldUnit().trim()));for(var line:r.ingredients()){ingredients.findByIdAndOrganizationId(line.ingredientId(),m.organizationId).orElseThrow(()->missing("Ingredient"));lines.save(new RecipeIngredient(recipe.id,line.ingredientId(),line.quantity(),line.unit().trim()));}audit.record(m,"RECIPE_CREATED","RECIPE",recipe.id,recipe.name);return recipe(m,recipe);}
List<ProductionResponse> batches(Membership m){return batches.findByOrganizationIdOrderByProducedAtDesc(m.organizationId).stream().map(x->batch(m,x)).toList();}
ProductionResponse produce(Membership m,ProductionRequest r){editor(m);var recipe=recipes.findByIdAndOrganizationId(r.recipeId(),m.organizationId).orElseThrow(()->missing("Recipe"));locations.findByIdAndOrganizationId(r.locationId(),m.organizationId).orElseThrow(()->missing("Location"));var expected=lines.findByRecipeId(recipe.id).stream().collect(Collectors.toMap(x->x.ingredientId,x->x));if(r.consumptions().isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"At least one ingredient lot must be consumed.");var batch=batches.save(new ProductionBatch(m.organizationId,recipe.id,r.locationId(),r.batchNumber().trim(),r.outputQuantity(),recipe.yieldUnit,clean(r.note())));for(var input:r.consumptions()){var lot=lots.findByIdAndOrganizationId(input.lotId(),m.organizationId).orElseThrow(()->missing("Ingredient lot"));if(!expected.containsKey(lot.ingredientId))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"This lot is not an ingredient in the selected recipe.");inventory.consumeForProduction(m,lot.id,r.locationId(),input.quantity(),"Production batch "+batch.batchNumber);consumptions.save(new ProductionConsumption(batch.id,lot.id,r.locationId(),input.quantity(),lot.unit));}audit.record(m,"PRODUCTION_RECORDED","PRODUCTION_BATCH",batch.id,batch.batchNumber);return batch(m,batch);}
ProductionPlanResponse preview(Membership m,ProductionPlanRequest r){return plan(m,r);}
ProductionResponse produceSuggested(Membership m,ProductionPlanRequest r){editor(m);var plan=plan(m,r);if(!plan.ready())throw new ResponseStatusException(HttpStatus.CONFLICT,plan.issue());var inputs=plan.lines().stream().flatMap(x->x.lots().stream()).map(x->new ConsumptionRequest(UUID.fromString(x.lotId()),x.quantity())).toList();var response=produce(m,new ProductionRequest(r.recipeId(),r.locationId(),plan.proposedBatchNumber(),r.outputQuantity(),inputs,r.note()));audit.record(m,"PRODUCTION_SUGGESTED_PLAN_CONFIRMED","PRODUCTION_BATCH",UUID.fromString(response.id()),"FEFO plan confirmed");return response;}
private ProductionPlanResponse plan(Membership m,ProductionPlanRequest r){editor(m);var recipe=recipes.findByIdAndOrganizationId(r.recipeId(),m.organizationId).orElseThrow(()->missing("Recipe"));var product=products.findByIdAndOrganizationId(recipe.productId,m.organizationId).orElseThrow(()->missing("Product"));var location=locations.findByIdAndOrganizationId(r.locationId(),m.organizationId).orElseThrow(()->missing("Location"));var scale=r.outputQuantity().divide(recipe.yieldQuantity,6,RoundingMode.HALF_UP);var result=new ArrayList<ProductionPlanLine>();String issue=null;for(var line:lines.findByRecipeId(recipe.id)){var ingredient=ingredients.findByIdAndOrganizationId(line.ingredientId,m.organizationId).orElseThrow();var required=line.quantity.multiply(scale).setScale(3,RoundingMode.HALF_UP);var remaining=required;var selected=new ArrayList<ConsumptionResponse>();var candidates=lots.findByOrganizationIdOrderByReceivedAtDesc(m.organizationId).stream().filter(x->x.ingredientId.equals(line.ingredientId)&&!quarantines.existsByLotIdAndActiveTrue(x.id)).sorted(Comparator.comparing((InventoryLot x)->x.expiryDate,Comparator.nullsLast(Comparator.naturalOrder())).thenComparing(x->x.receivedAt)).toList();for(var lot:candidates){if(!lot.unit.equalsIgnoreCase(line.unit))continue;var available=balances.findByLotIdAndLocationId(lot.id,r.locationId()).map(x->x.quantity).orElse(BigDecimal.ZERO);if(available.signum()<=0)continue;var take=available.min(remaining);selected.add(new ConsumptionResponse(lot.id.toString(),ingredient.name,lot.supplierBatchNumber,take,lot.unit));remaining=remaining.subtract(take);if(remaining.signum()<=0)break;}var allocated=required.subtract(remaining).setScale(3,RoundingMode.HALF_UP);if(remaining.signum()>0)issue="Not enough usable "+ingredient.name+" at "+location.name+". Need "+required+" "+line.unit+", with "+allocated+" available.";result.add(new ProductionPlanLine(ingredient.name,line.unit,required,allocated,selected));}return new ProductionPlanResponse(nextBatchNumber(m),recipe.name,product.name,location.name,r.outputQuantity(),recipe.yieldUnit,result,issue==null,issue);}
private String nextBatchNumber(Membership m){String base="PRD-"+LocalDate.now(ZoneOffset.UTC).format(DateTimeFormatter.BASIC_ISO_DATE)+"-";for(int n=1;n<10000;n++){String candidate=base+String.format("%04d",n);if(!batches.existsByOrganizationIdAndBatchNumber(m.organizationId,candidate))return candidate;}throw new ResponseStatusException(HttpStatus.CONFLICT,"Could not create a unique production batch number.");}
private RecipeResponse recipe(Membership m,Recipe x){var product=products.findByIdAndOrganizationId(x.productId,m.organizationId).orElseThrow();var response=lines.findByRecipeId(x.id).stream().map(l->{var i=ingredients.findByIdAndOrganizationId(l.ingredientId,m.organizationId).orElseThrow();return new RecipeLineResponse(i.id.toString(),i.name,l.quantity,l.unit);}).toList();return new RecipeResponse(x.id.toString(),product.id.toString(),product.name,x.name,x.yieldQuantity,x.yieldUnit,x.active,response);}
private ProductionResponse batch(Membership m,ProductionBatch x){var recipe=recipes.findByIdAndOrganizationId(x.recipeId,m.organizationId).orElseThrow();var product=products.findByIdAndOrganizationId(recipe.productId,m.organizationId).orElseThrow();var location=locations.findByIdAndOrganizationId(x.locationId,m.organizationId).orElseThrow();var list=consumptions.findByProductionBatchId(x.id).stream().map(c->{var l=lots.findByIdAndOrganizationId(c.lotId,m.organizationId).orElseThrow();var i=ingredients.findByIdAndOrganizationId(l.ingredientId,m.organizationId).orElseThrow();return new ConsumptionResponse(l.id.toString(),i.name,l.supplierBatchNumber,c.quantity,c.unit);}).toList();return new ProductionResponse(x.id.toString(),recipe.name,product.name,location.name,x.batchNumber,x.outputQuantity,x.outputUnit,x.producedAt,x.note,list);}
private ResponseStatusException missing(String type){return new ResponseStatusException(HttpStatus.NOT_FOUND,type+" not found.");}}
